      lsoNote1Title: '여름 목표!! \u{1F31E}',
      lsoNote1Content: '\u2022 새 레시피 3개 배우기\n\u2022 한 달에 두 번 이상 등산\n\u2022 책 2권 읽기\n\u2022 더 좋은 친구 되기\n\u2022 계속 미루던 프로젝트 시작하기\n\u2022 뭐든 더 자주 수락하기\n\n최고의 여름이 될 거야.',
      lsoNote2Title: '감사한 것들',
      lsoNote2Content: '\u2022 Jordan \u2014 항상 웃게 해줌\n\u2022 엄마의 요리(와 인내심)\n\u2022 친구들\n\u2022 새 친구 Taylor \u2014 좋은 인연인 것 같아\n\u2022 여름 저녁\n\u2022 언제든 다시 시작할 수 있다는 사실',
      lsoNote3Title: '좋은 하루',
      lsoNote3Content: '오늘 다 같이 바다에 갔다. Sam이 잠들어서 최악의 탄 자국이 생겼다. Jordan이 구름 순위 매기기를 시켰다.\n\n배가 아플 정도로 웃었다.\n\n이 느낌을 기억하고 싶다.',
      lsoNote4Title: '여름 목표 (수정)',
      lsoNote4Content: '<span class="crossed">\u2022 새 레시피 3개 배우기</span>\n<span class="crossed">\u2022 한 달에 두 번 이상 등산</span>\n\u2022 책 2권 읽기\n<span class="crossed">\u2022 더 좋은 친구 되기</span>\n<span class="crossed">\u2022 계속 미루던 프로젝트 시작하기</span>\n<span class="crossed">\u2022 뭐든 더 자주 수락하기</span>\n\n...다음 달에 하자',
      lsoNote5Title: 'Jordan에게 보내지 못한 메시지',
      lsoNote5Content: '<div class="unsent">어떻게 설명해야 할지 모르겠어. 상관없는 게 아니야. 너무 신경 쓰여서 아파. 그냥 어떻게 해야 할지\n\n왜 그냥 할 수가 없는 건지\n\n넌 이보다 더 나은 사람을</div>\n\n[초안 삭제됨]',
      lsoNote6Title: '왜',
      lsoNote6Content: '왜 가장 간단한 것도 이렇게 어려운 걸까\n\n나는 원래 나타나는 사람이었는데\n\n이제는 문자 하나도 답 못 해\n\n오늘 Jordan의 메시지를 열었다. 전부 읽었다. 키보드 위에서 10분 동안 손가락이 멈춰 있었다.\n\n아무것도 나오지 않았다.',
      lsoNote7Title: '내가 실망시키는 사람들',
      lsoNote7Content: 'Jordan\n엄마\nMika\nSam\nTaylor\n할머니\n\n...나',
      lsoNote8Title: '',
      lsoNote8Content: '피곤해',
      lsoNote9Title: '이 폰을 발견한 사람에게\u2014',
      lsoNote9Content: '이 폰을 발견한 사람에게\u2014\n\n이 메시지 속 사람들은 내가 만난 최고의 사람들이야. 그들은 노력했어. 정말 노력했어.\n\n나는 그냥 할 수가\n\n<span class="incomplete">|</span>',
      lsoCh1Prompt: 'Alex가 메시지를 응시한다. 머릿속을 스치는 건?',
      lsoCh1Opt1Label: '"아니. 네가 유일하게 옳은 존재야."',
      lsoCh1Opt1Thought: 'Alex의 눈이 따끔거린다. "아니"라고 타이핑하고 세 번 지운다.',
      lsoCh1Opt2Label: '"그렇게 간단하면 좋겠다."',
      lsoCh1Opt2Thought: 'Alex가 폰을 뒤집어 놓고 한참 동안 천장을 올려다본다.',
      lsoCh1Opt3Label: '...',
      lsoCh1Opt3Thought: 'Alex가 메시지를 읽는다. 다시 읽는다. 폰을 잠근다.',
      lsoCh2Prompt: 'Jordan의 말이 공중에 맴돈다. Alex는...',
      lsoCh2Opt1Label: '타이핑을 시작한다. 멈춘다. 다시 친다. 전부 지운다.',
      lsoCh2Opt1Thought: '"들여보내고 싶어. 문이 어디 있었는지 잊어버렸을 뿐이야."',
      lsoCh2Opt2Label: '화면이 어두워질 때까지 그냥 바라본다.',
      lsoCh2Opt2Thought: '화면이 꺼진다. Alex는 다시 켜지 않는다.',
      lsoCh3Prompt: '엄마가 Alex에게 집에 오라고 한다.',
      lsoCh3Opt1Label: '"응!! 갈게 \u{1F60A}" (Alex는 가지 않는다)',
      lsoCh3Opt1Thought: 'Alex가 갈 생각으로 메시지를 보낸다. 일요일이 지나간다.',
      lsoCh3Opt2Label: '"글쎄, 알려줄게"',
      lsoCh3Opt2Thought: 'Alex는 간다는 뜻이었다. 하지만 "글쎄"가 가장 솔직한 말이 되었다.',
      lsoCh3Opt3Label: '읽고 넘긴다',
      lsoCh3Opt3Thought: 'Alex가 메시지를 본다. 집, 냄새, 따뜻함 \u2014 감당이 안 된다.',
      lsoCh4Prompt: '친구들이 Alex를 원한다. Alex도 가고 싶다. 하지만...',
      lsoCh4Opt1Label: '"좋아아 나도 낄게!! \u{1F389}" (Alex는 당일 취소한다)',
      lsoCh4Opt1Thought: '토요일 아침. Alex는 옷을 입고 문 앞에 서 있다. "미안 갑자기 일이 생겼어"라고 보내고 다시 침대로 간다.',
      lsoCh4Opt2Label: '"솔직히 컨디션이 안 좋아, 너희끼리 가"',
      lsoCh4Opt2Thought: '몇 주 만에 Alex가 한 가장 솔직한 말. 그 메시지를 보내는 데 얼마나 큰 용기가 필요했는지 아무도 모른다.',
      lsoCh4Opt3Label: '답장하지 않는다',
