      lsoNote2Content: '\u2022 Jordan \u2014 her zaman güldürmeyi bilir\n\u2022 Annemin yemekleri (ve sabrı)\n\u2022 Ekip\n\u2022 Yeni arkadaş Taylor \u2014 iyi biri gibi hissettiriyor\n\u2022 Yaz akşamları\n\u2022 İstediğim zaman yeniden başlayabileceğim gerçeği',
      lsoNote3Title: 'Güzel gün',
      lsoNote3Content: 'Bugün herkesle plaja gittik. Sam uyuyakaldı ve en kötü güneş izlerini aldı. Jordan hepimize bulutları sıralattı.\n\nKarnım ağrıyana kadar güldüm.\n\nBu hissi hatırlamak istiyorum.',
      lsoNote4Title: 'Yaz Hedefleri (güncel)',
      lsoNote4Content: '<span class="crossed">\u2022 3 yeni tarif öğren</span>\n<span class="crossed">\u2022 Ayda en az iki kez doğa yürüyüşü</span>\n\u2022 2 kitap oku\n<span class="crossed">\u2022 Daha iyi bir arkadaş ol</span>\n<span class="crossed">\u2022 Hep bahsettiğim projeye başla</span>\n<span class="crossed">\u2022 Daha sık evet de</span>\n\n...belki gelecek ay',
      lsoNote5Title: "Jordan'a gönderilmemiş mesaj",
      lsoNote5Content: '<div class="unsent">Nasıl açıklayacağımı bilmiyorum. Umursamadığımdan değil. O kadar çok umursuyorum ki acıtıyor. Sadece bir türlü\n\nNeden yapamıyorum ki\n\nSen daha iyisini hak</div>\n\n[taslak silindi]',
      lsoNote6Title: 'Neden',
      lsoNote6Content: 'Neden en basit şeyler bile bu kadar zor\n\nBen bir zamanlar ortaya çıkan biriydim\n\nŞimdi bir mesaja bile cevap veremiyorum\n\nBugün Jordan\'ın mesajını açtım. Hepsini okudum. On dakika boyunca parmağım klavyenin üzerinde bekledi.\n\nHiçbir şey çıkmadı.',
      lsoNote7Title: 'Hayal kırıklığına uğrattığım insanlar',
      lsoNote7Content: 'Jordan\nAnne\nMika\nSam\nTaylor\nBüyükanne\n\n...ben',
      lsoNote8Title: '',
      lsoNote8Content: 'yorgun',
      lsoNote9Title: 'Bu telefonu bulan kişiye\u2014',
      lsoNote9Content: 'Bu telefonu bulan kişiye\u2014\n\nBu mesajlardaki insanların tanıdığım en iyi insanlar olduğunu bilmenizi istiyorum. Denediler. Gerçekten denediler.\n\nBen sadece yapamadım\n\n<span class="incomplete">|</span>',
      lsoCh1Prompt: 'Alex mesaja bakıyor. Aklından ne geçiyor?',
      lsoCh1Opt1Label: '"Hayır. Sen doğru olan tek şeysin."',
      lsoCh1Opt1Thought: 'Alex\'in gözleri yanıyor. "hayır" yazıp üç kez siliyor.',
      lsoCh1Opt2Label: '"Keşke o kadar basit olsaydı."',
      lsoCh1Opt2Thought: 'Alex telefonu ters çevirip masaya koyuyor ve uzun süre tavana bakıyor.',
      lsoCh1Opt3Label: '...',
      lsoCh1Opt3Thought: 'Alex mesajı okuyor. Tekrar okuyor. Telefonu kilitliyor.',
      lsoCh2Prompt: 'Jordan\'ın sözleri havada asılı kalıyor. Alex...',
      lsoCh2Opt1Label: 'Yazmaya başlıyor. Duruyor. Tekrar yazıyor. Her şeyi siliyor.',
      lsoCh2Opt1Thought: '"Seni içeri almak istiyorum. Sadece kapıyı nereye koyduğumu unuttum."',
      lsoCh2Opt2Label: 'Ekran kararana kadar bakıyor.',
      lsoCh2Opt2Thought: 'Ekran kapanıyor. Alex tekrar açmıyor.',
      lsoCh3Prompt: 'Anne Alex\'in eve gelmesini istiyor.',
      lsoCh3Opt1Label: '"Evet!! Orada olacağım \u{1F60A}" (Alex hiç gitmiyor)',
      lsoCh3Opt1Thought: 'Alex mesajı gitme niyetiyle yazıyor. Pazar gelip geçiyor.',
      lsoCh3Opt2Label: '"Belki, haber veririm"',
      lsoCh3Opt2Thought: 'Alex evet demek istiyor. Ama "belki" en dürüst kelimesi oluyor.',
      lsoCh3Opt3Label: 'Okundu olarak bırak',
      lsoCh3Opt3Thought: 'Alex mesajı görüyor. Evin düşüncesi, kokular, sıcaklık \u2014 çok fazla.',
      lsoCh4Prompt: 'Ekip Alex\'i istiyor. Alex de orada olmak istiyor. Ama...',
      lsoCh4Opt1Label: '"EVEETT beni de sayın!! \u{1F389}" (Alex günü gelince iptal eder)',
      lsoCh4Opt1Thought: 'Cumartesi sabahı. Alex giyinmiş. Kapının önünde duruyor. "kusura bakma bir şey çıktı" yazıp yatağa geri dönüyor.',
      lsoCh4Opt2Label: '"açıkçası iyi hissetmiyorum, siz gidin"',
      lsoCh4Opt2Thought: 'Alex\'in haftalardır söylediği en dürüst şey. O mesajı göndermenin ne kadar zor olduğunu kimse bilmiyor.',
      lsoCh4Opt3Label: 'Cevap verme',
      lsoCh4Opt3Thought: 'Bildirim rozeti üç gün orada duruyor, Alex okumadan temizliyor.',
      lsoCh5Prompt: 'Yeni bir arkadaş ulaşıyor. Basit. Kolay. Ama artık hiçbir şey basit değil.',
      lsoCh5Opt1Label: '"Tabii! Perşembe nasıl?" (çarşamba gecesi iptal eder)',
      lsoCh5Opt1Thought: 'Alex gerçekten gitmek istiyor. İptal mesajını göndermeyi bu kadar zor yapan da bu.',
      lsoCh5Opt2Label: '"çok teşekkürler ama son zamanlarda o modda değilim"',
      lsoCh5Opt2Thought: 'Taylor\'ın nezaketi bunu kolaylaştırmıyor, zorlaştırıyor.',
      lsoCh5Opt3Label: 'Okundu. Cevap yok.',
      lsoCh5Opt3Thought: 'Hayal kırıklığına uğratacak bir kişi daha. Liste uzamaya devam ediyor.',
      lsoCh6Prompt: 'Son giriş tamamlanmamış. Bu sessizlik sizin için ne anlama geliyor?',
      lsoCh6Opt1Label: 'Bir durak. Bir son değil. Alex bu cümleyi bir gün bitirecek.',
      lsoCh6Opt2Label: 'Yazamadıkları bir veda.',
      lsoCh6Opt3Label: 'Buna karar vermek bize düşmez.',


