      lsoNote1Content: '\u2022 学3个新食谱\n\u2022 每月至少爬山两次\n\u2022 读2本书\n\u2022 做更好的朋友\n\u2022 开始那个一直说要做的项目\n\u2022 多说"好"\n\n这将是最好的夏天。',
      lsoNote2Title: '感恩的事',
      lsoNote2Content: '\u2022 Jordan \u2014 总是知道怎么逗我笑\n\u2022 妈妈的厨艺（和耐心）\n\u2022 小伙伴们\n\u2022 新朋友Taylor \u2014 感觉是值得深交的人\n\u2022 夏天的傍晚\n\u2022 随时都可以重新开始这件事',
      lsoNote3Title: '美好的一天',
      lsoNote3Content: '今天和大家一起去了海边。Sam睡着了晒出了最糟糕的印子。Jordan让我们给云朵排名。\n\n笑到肚子疼。\n\n我想记住这种感觉。',
      lsoNote4Title: '夏日目标（更新版）',
      lsoNote4Content: '<span class="crossed">\u2022 学3个新食谱</span>\n<span class="crossed">\u2022 每月至少爬山两次</span>\n\u2022 读2本书\n<span class="crossed">\u2022 做更好的朋友</span>\n<span class="crossed">\u2022 开始那个一直说要做的项目</span>\n<span class="crossed">\u2022 多说"好"</span>\n\n...也许下个月吧',
      lsoNote5Title: '给Jordan没发出去的消息',
      lsoNote5Content: '<div class="unsent">我不知道怎么解释。不是我不在乎。我太在乎了以至于很痛。只是我没办法\n\n为什么我就是做不到\n\n你值得比这更好的</div>\n\n[草稿已删除]',
      lsoNote6Title: '为什么',
      lsoNote6Content: '为什么最简单的事情都这么难\n\n我曾经是个会出现的人\n\n现在连回一条消息都做不到\n\n今天打开了Jordan的消息。全看了。拇指在键盘上悬了十分钟。\n\n什么都打不出来。',
      lsoNote7Title: '我正在让这些人失望',
      lsoNote7Content: 'Jordan\n妈妈\nMika\nSam\nTaylor\n奶奶\n\n...我自己',
